export const EU_WAVE_TRANSLATIONS: Record<string, Record<EuWaveLocale, string>> = Object.fromEntries(
  Object.entries(EU_WAVE_ROWS).map(([source, values]) => [source, Object.fromEntries(EU_WAVE_LOCALES.map((locale, index) => [locale, values[index]]))]),
) as Record<string, Record<EuWaveLocale, string>>;
